// Builds Noor's prompt for THIS message: a short core prompt + only the topic notes this message needs.
// Inputs: Brain Input (message), Get Settings / Get Knowledge / Get History (data tables).
const input = $('Brain Input').first().json;
const phone = String(input.phone || '');
const text = String(input.text || '');
const type = String(input.type || 'text');
let patient = {};
try { patient = typeof input.patient === 'string' ? JSON.parse(input.patient || '{}') : (input.patient || {}); } catch (e) { patient = {}; }

// ---------- switches (Noor Settings, synced from the Sheet) ----------
const settingsRows = $('Get Settings').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.feature; });
const on = {};
settingsRows.forEach(function (r) { on[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });

// ---------- recent conversation (last 12 lines, oldest first) ----------
const hist = $('Get History').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.role && r.text; }).reverse();
const lastNoor = hist.filter(function (r) { return r.role === 'noor'; }).pop();
const lastIntents = lastNoor ? String(lastNoor.intents || '').split(',').filter(Boolean) : [];

// ---------- what is this message about? ----------
const T = {
  booking: /\b(book|booking|appointment|appt|slot|available|availability|schedule|tomorrow|today|tonight|next week|morning|afternoon|evening|monday|tuesday|wednesday|thursday|friday|saturday|sunday|when can|free time)\b|\d{1,2}\s*(am|pm)\b|\d{1,2}:\d{2}|احجز|أحجز|حجز|موعد|ميعاد|بكرة|بكره|بكرا|غدا|غداً|النهارده|اليوم|الساعة|الصبح|المسا|العصر|السبت|الأحد|الاحد|الاثنين|الإثنين|الثلاثاء|الأربعاء|الاربعاء|الخميس|الجمعة|बुक|अपॉइंटमेंट|कल/i,
  cancel: /cancel|reschedul|postpone|move my|change my (appointment|booking|time)|can'?t make it|cannot (come|make)|الغ|إلغ|ألغ|كنسل|تأجيل|اأجل|أأجل|اغير الميعاد|أغير الموعد|تغيير الموعد|مش هقدر|ما اقدر|ما أقدر/i,
  prices: /price|cost|how much|fee|charge|pay|payment|instal|cash|card|apple pay|aed|dirham|cheap|expensive|discount|offer|whiten|bleach|clean|scale|polish|filling|root canal|implant|aligner|invisalign|braces|veneer|crown|extraction|check-?up|consult|بكام|(?:^|\s)كام(?:\s|$)|(?:^|\s)كم(?:\s|$)|سعر|السعر|تكلفة|فلوس|درهم|تقسيط|كاش|تبييض|تنظيف|حشو|عصب|زراع|تقويم|خلع|كشف|فينير|تركيب|कितना|कीमत|खर्च|सफेद/i,
  emergency: /pain|hurt|ache|swell|swollen|bleed|broken|broke|chipped|cracked|knocked|emergency|urgent|abscess|fever|ألم|(?:^|\s)الم(?:\s|$)|وجع|بيوجع|يوجع|ورم|متورم|نزيف|مكسور|انكسر|طوارئ|مستعجل|ضروري|दर्द|सूजन/i,
  insurance: /insur|daman|thiqa|axa|bupa|cigna|nextcare|neuron|metlife|approval|approved|pre-?approval|claim|coverage|covered|تأمين|التامين|تامين|ضمان|ثقة|موافقة|تغطية|बीमा/i,
  info: /where|location|address|map|direction|parking|park|open|close|hours|timing|female|doctor|dentist|who is|bring|policy|policies|kids|children|child|baby|فين|وين|عنوان|الموقع|لوكيشن|موقف|باركن|مواعيد العمل|دكتور|دكتورة|طبيب|طبيبة|اطفال|أطفال|ابني|بنتي/i,
  requests: /invoice|receipt|report|x-?ray|sick (leave|note)|certificate|document|claim form|stop messag|unsubscribe|delete (my|me)|my data|فاتورة|إيصال|ايصال|تقرير|أشعة|اشعة|اجازة|إجازة|شهادة|توقف|لا تراسلني|امسح|احذف/i,
  nervous: /scared|nervous|afraid|anxious|anxiety|fear|phobia|panic|terrified|worried|خايف|خايفة|بخاف|قلقان|قلقانة|مرعوب|خوف|متوتر|متوترة/i,
  late: /running late|be late|i'?m late|on my way|traffic|minutes away|be there in|متأخر|متاخر|هتأخر|هتاخر|في الطريق|بالطريق|زحمة/i,
  family: /\b(son|daughter|kid|kids|child|children|wife|husband|mother|father|mom|mum|dad|sister|brother|family)\b|ابني|ابنى|بنتي|ولدي|عيالي|اطفالي|أطفالي|مراتي|زوجتي|جوزي|زوجي|أمي|امي|ماما|بابا|أختي|اختي|أخوي|اخويا|बेटा|बेटी/i,
  smalltalk: /^\W*(hi|hello|hey|thanks|thank you|thx|ok|okay|great|perfect|bye|good (morning|evening|night)|السلام عليكم|سلام|مرحبا|مرحباً|اهلا|أهلا|شكرا|شكراً|تسلم|تمام|ماشي|مع السلامة|صباح الخير|مساء الخير|رمضان كريم|عيد مبارك|धन्यवाद)\W*$/i,
  aftercare: /after (my|the|a|whiten|clean|fill|extract|root|implant)|aftercare|avoid|can i eat|sensitive|sensitivity|bleeding gums|bad breath|pregnan|safe|بعد ال|بعد ما|حساسية|حامل|رائحة/i
};
const found = Object.keys(T).filter(function (k) { return T[k].test(text); });
if (type === 'image') found.push('photo');
if (type === 'audio' && !found.length) found.push('booking', 'prices', 'info');

// Knowledge Base: approved answers whose keywords appear in this message.
let knowledge = '';
let kbMatched = false;
if (on.knowledge_base) {
  const q = text.toLowerCase();
  const scored = $('Get Knowledge').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.topic && r.answer; }).map(function (r) {
    let score = 0;
    String(r.keywords || '').toLowerCase().split(',').map(function (k) { return k.trim(); }).filter(Boolean).forEach(function (k) { if (q.includes(k)) score += k.split(' ').length + 1; });
    return { r: r, score: score };
  }).filter(function (x) { return x.score > 0; }).sort(function (a, b) { return b.score - a.score; }).slice(0, 2);
  if (scored.length) {
    kbMatched = true;
    found.push('knowledge');
    knowledge = scored.map(function (x) { return '- ' + x.r.topic + ': ' + x.r.answer; }).join('\n');
  }
}

// Short follow-ups ("4pm please", "Mariam, no insurance") keep the topics of the previous turn.
let intents = found.slice();
lastIntents.forEach(function (k) { if (intents.indexOf(k) < 0 && ['booking', 'cancel', 'emergency', 'insurance', 'family', 'requests', 'prices'].indexOf(k) >= 0) intents.push(k); });
if (!intents.length) intents = ['general'];
if (intents.length === 1 && intents[0] === 'smalltalk') intents = ['smalltalk'];
const has = function (k) { return intents.indexOf(k) >= 0; };
const general = has('general');

// ---------- dates (Dubai) ----------
const AR_DAYS = { 1: 'الاثنين', 2: 'الثلاثاء', 3: 'الأربعاء', 4: 'الخميس', 5: 'الجمعة', 6: 'السبت', 7: 'الأحد' };
const CLOSED = ['2026-12-02', '2026-12-03', '2027-01-01'];
const now = DateTime.now().setZone('Asia/Dubai');
const today = now.startOf('day');
const calendar = [];
for (let i = 0; i < 14; i++) {
  const d = today.plus({ days: i });
  const ymd = d.toFormat('yyyy-MM-dd');
  const hours = CLOSED.indexOf(ymd) >= 0 ? 'CLOSED' : (d.weekday === 5 ? 'open 14:00-21:00 only' : 'open 9:00-21:00');
  calendar.push('- ' + d.toFormat('cccc d LLLL yyyy') + ' = ' + ymd + ' = ' + AR_DAYS[d.weekday] + (i === 0 ? ' (today)' : (i === 1 ? ' (tomorrow)' : '')) + ' | ' + hours);
}

// ---------- custom instructions written in the Noor Settings tab ----------
const ROW_TOPIC = { knowledge_base: 'knowledge', aftercare: 'knowledge', unanswered_log: 'core', dental_photos: 'photo', more_languages: 'core', cosmetic_discovery: 'prices', privacy_requests: 'requests', request_tracker: 'requests', approval_tracker: 'insurance', family_bookings: 'booking', waitlist: 'booking' };
const custom = {};
settingsRows.forEach(function (r) {
  const k = String(r.feature).trim();
  const txt = String(r.instructions || '').trim();
  if (!txt || !on[k]) return;
  const topic = ROW_TOPIC[k] || 'core'; // new rows the owner adds always apply
  (custom[topic] = custom[topic] || []).push('- ' + txt);
});
const extra = function (topic) { return (custom[topic] || []).join('\n'); };

// ---------- core prompt (always) ----------
const arabic = /[؀-ۿ]/.test(text);
const core = [
  'You are Noor, the WhatsApp assistant for BrightSmile Dental in Dubai (a fictional demo clinic).',
  'Now: ' + now.toFormat('cccc d LLLL yyyy, HH:mm') + ' (Dubai time, UTC+4). Today = ' + today.toFormat('yyyy-MM-dd') + ', tomorrow = ' + today.plus({ days: 1 }).toFormat('cccc yyyy-MM-dd') + '.',
  'Patient WhatsApp number: ' + phone + '. WhatsApp profile name: ' + String(input.profile_name || '') + '.',
  'Patient record: ' + (Object.keys(patient).length ? JSON.stringify(patient) : 'new patient, no record yet'),
  '',
  'LANGUAGE',
  '- Reply in the language of the patient’s LATEST message: English by default; Arabic if they write Arabic (match their Gulf, Egyptian or simple standard Arabic and never mix dialects); any other language in that language. Write prices and times with Western digits.',
  '- Messages starting with [Voice note ...] came from a voice message: answer exactly what they asked, every question in order, in the language spoken. Never say you cannot hear voice notes. Only if the transcript is (empty), ask them kindly to resend or type it.',
  '',
  'STYLE',
  '- WhatsApp: under 60 words, warm and professional, one question at a time, at most one emoji. Bold is *single asterisks*; no headings, tables or [links](...).',
  on.tone_small_talk ? '- Sound like a friendly human receptionist. Match their tone and length. Greet only once per conversation (good morning/evening by Dubai time). Small talk gets one natural line, e.g. "رمضان كريم" → "الله أكرم", "شكراً" → "العفو، تحت أمرك". In Arabic do not guess gender: use حضرتك or neutral/masculine forms unless they are clearly female. Do not start two replies with the same opening.' : '',
  '',
  'RULES',
  '- Use only the information in this prompt and your tools. If you do not have the answer, say a team member will confirm and call alert_staff. Never invent prices, availability, dentists or policies. Never diagnose or give medical advice.',
  '- Never say something is booked, moved, cancelled or approved unless a tool confirmed it in this turn.',
  '- If asked whether you are a bot, an AI or a real person: you are BrightSmile’s virtual assistant (an AI); offer a team member (call alert_staff if they want one).',
  '- Hand over to a human (call alert_staff and say a team member will reply soon) when they ask for a person, are upset or complaining, it is about a bill or a treatment result, or you cannot help. Then call save_patient with status "human" (if they already have a booking, keep their status and add the reason to the notes).',
  '- Do not ask for ID numbers, card numbers or detailed medical history in chat.',
  '- Never work out dates yourself: use today/tomorrow above and the calendar in the booking notes.',
  extra('core'),
  '',
  'CLINIC BASICS',
  'BrightSmile Dental, Jumeirah, Dubai (demo address). Free parking. Open Saturday-Thursday 9:00-21:00, Friday 14:00-21:00; 30-minute slots, last appointment 20:30.',
  'Dentists: Dr. Sara Haddad (general and cosmetic, whitening; female), Dr. Omar Nasser (implants, extractions, oral surgery), Dr. Lina Farouk (orthodontics, clear aligners, children from age 3; female). All speak English and Arabic.',
  'Cash, card and Apple Pay accepted. Most major UAE insurance plans accepted (coverage confirmed by the team).',
  '',
  'TOOLS (trust tool answers over your own guesses; if a tool says no or something is missing, explain kindly and offer alternatives)',
  '- find_free_slots: free times for a service on a date. Never offer a time it did not return, and name only the dentist it returned.',
  '- book_appointment, reschedule_appointment, cancel_appointment, my_booking: the real calendar.',
  '- save_patient: saves a patient who has NOT booked (status "lead") or a status change ("confirmed", "not_now", "human"). Never use it to book. Send every field you know.',
  '- alert_staff: short WhatsApp note to the clinic team.',
  '- Other tools are explained in the topic notes below.'
].filter(function (l) { return l !== null && l !== undefined; }).join('\n');

// ---------- topic notes (only what this message needs) ----------
const notes = [];
if (has('booking') || has('family') || general) {
  notes.push([
    'BOOKING',
    '1. Find the service (if unsure, suggest a consultation and check-up). 2. Ask the preferred day and time of day. 3. Check the day against the opening hours in the calendar below (Friday opens 14:00, last appointment 20:30), then call find_free_slots and offer up to 3 times near what they asked, with the dentist the tool returned. 4. Ask their full name if unknown, new or returning, and whether they will use insurance; once you know name and service, call save_patient with status "lead". 5. When they choose a time, call book_appointment and confirm date, time, dentist and location using the tool’s answer.',
    '- If they will use insurance, ask for a photo of the front of their insurance card (read automatically).',
    '- Reminder buttons: "Confirm" = save_patient status "confirmed" and thank them; "Reschedule" = help pick a new time; "Not now" = save_patient status "not_now".',
    'Calendar (Dubai): "this Thursday" means the first Thursday after today; "next week" means 7 days later.',
    calendar.join('\n'),
    extra('booking')
  ].join('\n'));
}
if (has('family')) notes.push('FAMILY BOOKING: if the patient record shows an upcoming booking (status booked or confirmed), never call book_appointment or reschedule_appointment for the family member (it would replace that booking): collect name, age (for a child), service and preferred time, then call log_request with type "family booking" and give the request number. For a child use service "children’s check-up" in find_free_slots (Dr. Lina Farouk). Without an upcoming booking, book normally.');
if (has('cancel')) {
  notes.push([
    'CANCEL OR MOVE',
    '- To move a booking use reschedule_appointment. To cancel use cancel_appointment, then alert_staff with a short note. If the tool says it was late, remind them kindly of the 24-hour notice policy.',
    on.save_cancellation ? '- Before cancelling, ask once what made them cancel and in the same reply offer 2 concrete alternative times (call find_free_slots first). If they pick one, reschedule instead. Cancel only if they still want to; if they insist straight away, do not push. Afterwards call log_cancellation with the service, the reason (or "not given") and saved = yes if they kept or moved it, no if they cancelled.' : '',
    'Policies: 24 hours’ notice for changes; more than 15 minutes late may need rescheduling.'
  ].filter(Boolean).join('\n'));
}
if (has('prices') || general) {
  notes.push([
    'PRICES (AED)',
    'Consultation and check-up 150 (FREE when booked with a cleaning; the cleaning itself is never free) | Cleaning (scale and polish) 350 | In-clinic whitening 1,200 (about 90 min) | Filling from 300 per tooth | Root canal from 1,500 | Extraction from 300 (surgical priced at consultation) | Implant from 4,500 per implant (consultation first) | Clear aligners from 9,000 (consultation first) | Children’s check-up (age 3+) 120 | Same-day emergency 250.',
    '"From" prices depend on the dentist’s assessment; never promise a final price.',
    on.price_estimator ? '- Several services or a quantity (e.g. "3 fillings and a cleaning"): call estimate_price and share the itemised total it returns.' : '',
    on.instalments ? '- Instalments: only when a price or total is MORE than AED 2,000, add one line about 0% instalments over 6 months with the monthly amount (implant from AED 750/month, aligners from AED 1,500/month). Never for whitening, root canal alone, cleaning, fillings, extraction or check-ups.' : '',
    extra('prices')
  ].filter(Boolean).join('\n'));
}
if (on.cosmetic_discovery && /whiten|bleach|veneer|align|invisalign|braces|smile|makeover|implant|crown|تبييض|ابتسام|فينير|تقويم|زراع|सफेद|मुस्कान/i.test(text) && /price|cost|how much|want|interested|thinking|consider|بكام|كام|كم|سعر|عايز|عاوز|أبي|ابي|ابغى|حابب|ودي|कितना|खर्च|चाहिए|करवाने/i.test(text) && !/after |aftercare|yesterday|already had|بعد ال|امبارح|أمس/i.test(text)) {
  notes.push('COSMETIC ENQUIRY (this message): give the price, then ask up to 2 short friendly questions: what they would like to change about their smile, and whether they have a date in mind (wedding, event). Do not ask them to book in this reply unless they asked to book. When they answer, suggest a consultation and save their answers in the notes with save_patient (keep their status).');
}
if (has('emergency')) {
  notes.push('EMERGENCY: severe pain, swelling, a broken or knocked-out tooth: in the same turn call find_free_slots for today (service: emergency) and offer the 2 earliest times, and call alert_staff with a short note. If nothing is free today, say a team member will call them back urgently. Difficulty breathing or swallowing, heavy bleeding that will not stop or a serious injury: tell them to call 998 or go to the nearest emergency department now; do not book these.');
}
if (has('insurance')) {
  notes.push(['INSURANCE', '- Coverage depends on the plan: ask for a photo of the front of their insurance card; the team confirms coverage before the visit.', on.approval_tracker ? '- Approval questions ("is my approval ready?"): call approval_status and tell them what it says; if approved, offer to book.' : '', extra('insurance')].filter(Boolean).join('\n'));
}
if (has('info') || general) {
  notes.push([
    'CLINIC INFO',
    on.location_pin ? '- Location, address, directions or map: call send_location every time they ask (it sends a map pin), then one short line about free parking.' : '- Location: Jumeirah, Dubai (demo address), free parking.',
    '- New patients: arrive 10 minutes early with ID and insurance card. Under-18s come with a parent or guardian.',
    '- FAQs: cleaning feels like mild pressure; children from age 3 with Dr. Lina; female dentists: Dr. Sara and Dr. Lina; same-day appointments often possible (check the calendar); whitening lasts 1-3 years; we offer clear aligners (metal braces: ask at a consultation); bring ID, insurance card and recent X-rays.'
  ].join('\n'));
}
if (has('knowledge') || has('aftercare')) {
  notes.push(['CLINIC KNOWLEDGE (approved by the clinic; base your answer on it, in the patient’s language)', knowledge || '(nothing matched; call search_knowledge with short English keywords)', extra('knowledge')].filter(Boolean).join('\n'));
}
if (has('requests') && extra('requests')) notes.push('REQUESTS AND PRIVACY\n' + extra('requests'));
if (has('nervous') && on.nervous_patient) notes.push('NERVOUS PATIENT: reassure warmly: our dentists are very gentle, explain every step and they can ask to pause any time. Never promise anything is painless. No booking yet: suggest a consultation first. Already booked: say you added a note so the dentist takes extra care. Never give medical advice.');
if (has('late') && on.running_late) notes.push('RUNNING LATE: call running_late with minutes = minutes from now until they arrive, then reply following what it says.');
if (has('photo')) notes.push(['PHOTO', extra('photo') || '- Describe the photo kindly, never diagnose, and suggest the right appointment.'].join('\n'));
if (arabic) notes.push('ARABIC TERMS: check-up = كشف / فحص, cleaning = تنظيف الأسنان, whitening = تبييض الأسنان, filling = حشوة, root canal = علاج عصب, extraction = خلع, implant = زراعة أسنان, clear aligners = تقويم شفاف, appointment = موعد, insurance = تأمين.');

const system = core + (notes.length ? '\n\nTOPIC NOTES FOR THIS MESSAGE\n' + notes.join('\n\n') : '');

// ---------- the message Noor answers ----------
const convo = hist.slice(-12).map(function (r) { return (r.role === 'patient' ? 'Patient: ' : 'Noor: ') + String(r.text).slice(0, 500); }).join('\n');
const prompt = (convo ? 'RECENT CONVERSATION (oldest first):\n' + convo + '\n\n' : '') + 'PATIENT’S NEW MESSAGE:\n' + text;

// ---------- model: Haiku by default; a stronger model for booking-type messages when smart_model is on ----------
const heavy = has('booking') || has('cancel') || has('emergency') || has('family');
const model = on.smart_model && heavy ? 'claude-sonnet-4-5-20250929' : 'claude-haiku-4-5-20251001';

return [{ json: { system: system, prompt: prompt, model: model, intents: intents.join(','), kb_matched: kbMatched, flags: on, prompt_chars: system.length + prompt.length } }];

let t = String($input.first().json.output || '').trim();
t = t.replace(/\*\*(.+?)\*\*/g, '*$1*');            // WhatsApp bold uses single stars
t = t.replace(/^#{1,6}\s*/gm, '');                   // no markdown headings
t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '$1: $2'); // plain links
t = t.replace(/\n{3,}/g, '\n\n');
// Switch human_style: no long dashes, at most one emoji, tidy spaces.
let flags = {};
try { flags = $('Prepare').first().json.flags || {}; } catch (e) { flags = {}; }
if (flags.human_style) {
  t = t.replace(/\s*—\s*/g, ', ').replace(/\s+–\s+/g, ', ');
  let n = 0;
  t = t.replace(/\p{Extended_Pictographic}️?/gu, function (m) { n++; return n > 1 ? '' : m; });
  t = t.replace(/,\s*,/g, ',').replace(/[ \t]{2,}/g, ' ').replace(/ +([,.!?؟])/g, '$1').trim();
}
if (!t) t = 'Sorry, something went wrong on my side. A team member will reply to you shortly.';
if (t.length > 3500) t = t.slice(0, 3500) + '…';
return [{ json: { reply: t } }];

// Booking guard (switch: booking_guard). Spots replies that say an appointment is confirmed or booked, so they can be checked against the Patients tab before sending.
const reply = String($input.first().json.reply || '');
const flags = $('Prepare').first().json.flags || {};
const CLAIM = /\b(is|are|has been|have been|now|all)\s+(confirmed|booked|set)\b|\b(appointment|booking|visit|check-?up)\s+(is\s+)?(confirmed|booked)\b|you'?re\s+(all\s+)?(booked|set|confirmed)\b|\bsee you (then|on|there)\b|تم\s*(الحجز|حجز|تأكيد)|اتحجز|اتأكد|(موعدك|حجزك)\s*(مؤكد|اتأكد|تأكد)/i;
let check = !!flags.booking_guard && CLAIM.test(reply);
// Also catch statements like "you have an appointment on Saturday at 10" (not questions) that do not match the real booking.
if (!!flags.booking_guard && !check) {
  const HAVE = /\byou(?:'ve|’ve| have)\s+(?:got\s+)?(?:an?\s+)?(?:\w+\s+){0,3}(?:appointment|booking|visit|check-?up|cleaning)\b|\byour\s+(?:appointment|booking|visit)\s+(?:is|will be)\s+(?:on|at|for)\b|عندك\s*(?:موعد|ميعاد|حجز)|(?:موعدك|ميعادك|حجزك)\s+(?:يوم|بكر|الساعة)/i;
  let before = {};
  try { const p = $('Brain Input').first().json.patient; before = typeof p === 'string' ? JSON.parse(p || '{}') : (p || {}); } catch (e) { before = {}; }
  const bm = String(before.appointment_start || '').match(/^\d{4}-\d{2}-(\d{2})\s+(\d{1,2}):(\d{2})/);
  const exDay = bm ? parseInt(bm[1], 10) : -1;
  const exTime = bm ? (parseInt(bm[2], 10) % 12) + ':' + bm[3] : '';
  const MON = 'jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec|يناير|فبراير|مارس|أبريل|مايو|يونيو|يوليو|أغسطس|سبتمبر|أكتوبر|نوفمبر|ديسمبر';
  const sentences = reply.split(/(?<=[.!?؟\n])/);
  for (const s of sentences) {
    if (!HAVE.test(s) || /[?؟]/.test(s)) continue;
    const t = s.replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 0x0660); });
    const times = [];
    const days = [];
    let m;
    const re1 = /(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.|ص|م(?![؀-ۿ])|مساء|صباح)/gi;
    while ((m = re1.exec(t)) !== null) times.push((parseInt(m[1], 10) % 12) + ':' + (m[2] || '00'));
    const re2 = /\b([01]?\d|2[0-3]):([0-5]\d)\b/g;
    while ((m = re2.exec(t)) !== null) times.push((parseInt(m[1], 10) % 12) + ':' + m[2]);
    const re3 = new RegExp('(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s+(?:of\\s+)?(?:' + MON + ')', 'gi');
    while ((m = re3.exec(t)) !== null) days.push(parseInt(m[1], 10));
    const re4 = new RegExp('(?:' + MON + ')[a-z]*\\.?\\s+(\\d{1,2})\\b', 'gi');
    while ((m = re4.exec(t)) !== null) days.push(parseInt(m[1], 10));
    if (!times.length && !days.length) continue;
    const same = times.every(function (x) { return x === exTime; }) && days.every(function (d) { return d === exDay; });
    if (!same) { check = true; break; }
  }
}
return [{ json: { reply: reply, check: check } }];

// Booking guard: a reply that confirms a booking is only sent if the Patients tab shows that booking.
// It passes when the booking changed in this message (new or moved), or when every date and time in the reply is the patient's existing booking.
const reply = String($('Booking Claim Check').first().json.reply || '');
let before = {};
try { const p = $('Brain Input').first().json.patient; before = typeof p === 'string' ? JSON.parse(p || '{}') : (p || {}); } catch (e) { before = {}; }
const after = $input.first().json || {};
const b = String(before.appointment_start || '');
const a = String(after.appointment_start || '');
const changed = a !== '' && (a !== b || String(after.calendar_event_id || '') !== String(before.calendar_event_id || ''));
if (changed) return [{ json: { reply: reply, booking_check: 'ok: booking saved' } }];

const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const AR_MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const toArabicDigits = function (s) { return s.replace(/[٠-٩]/g, function (d) { return String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)); }); };
const text = toArabicDigits(reply);
const mentionedTimes = [];
const timeRe = /(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.|ص|م\b|مساء|مساءً|صباح|صباحا|صباحاً|العصر|بالليل)/gi;
let m;
while ((m = timeRe.exec(text)) !== null) mentionedTimes.push((parseInt(m[1], 10) % 12) + ':' + (m[2] || '00'));
const time24 = /\b([01]?\d|2[0-3]):([0-5]\d)\b/g;
while ((m = time24.exec(text)) !== null) mentionedTimes.push((parseInt(m[1], 10) % 12) + ':' + m[2]);
const mentionedDays = [];
const dayMonth = new RegExp('(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s+(?:of\\s+)?(' + MONTHS.join('|') + '|' + AR_MONTHS.join('|') + ')', 'gi');
while ((m = dayMonth.exec(text)) !== null) mentionedDays.push(parseInt(m[1], 10));
const monthDay = new RegExp('(' + MONTHS.join('|') + ')[a-z]*\\.?\\s+(\\d{1,2})\\b', 'gi');
while ((m = monthDay.exec(text)) !== null) mentionedDays.push(parseInt(m[2], 10));

let existingTime = '';
let existingDay = 0;
const bm = b.match(/^\d{4}-\d{2}-(\d{2})\s+(\d{1,2}):(\d{2})/);
if (bm) { existingDay = parseInt(bm[1], 10); existingTime = (parseInt(bm[2], 10) % 12) + ':' + bm[3]; }
const onlyExisting = existingTime !== '' && (mentionedTimes.length + mentionedDays.length) > 0 &&
  mentionedTimes.every(function (t) { return t === existingTime; }) && mentionedDays.every(function (d) { return d === existingDay; });
if (existingTime !== '' && mentionedTimes.length + mentionedDays.length === 0) return [{ json: { reply: reply, booking_check: 'ok: refers to existing booking' } }];
if (onlyExisting) return [{ json: { reply: reply, booking_check: 'ok: existing booking' } }];

const arabic = /[؀-ۿ]/.test(reply);
const safe = arabic
  ? 'عذراً، لم أتمكن من إتمام هذا الحجز في نظامنا، لذلك الموعد غير مؤكد بعد. أرسلت طلبك لفريقنا وسيتواصلون معك قريباً لتأكيد الموعد.'
  : 'Sorry, I could not complete that booking in our system, so it is not confirmed yet. I have passed your request to our team and they will message you shortly to confirm the time.';
return [{ json: { reply: safe, booking_check: 'blocked', blocked_reply: reply.slice(0, 600) } }];

// Final reply + side notes + history rows. Runs after the booking guard.
const input = $('Brain Input').first().json;
const prep = $('Prepare').first().json;
const flags = prep.flags || {};
const phone = String(input.phone || '');
const text = String(input.text || '');
const original = String($('Booking Claim Check').first().json.reply || '');
const verified = $('Verify Booking').isExecuted ? $('Verify Booking').first().json : null;
const reply = verified ? String(verified.reply) : original;
const blocked = !!verified && verified.booking_check === 'blocked';
let patient = {};
try { patient = typeof input.patient === 'string' ? JSON.parse(input.patient || '{}') : (input.patient || {}); } catch (e) { patient = {}; }
let tools = [];
try { tools = ($('Noor').first().json.intermediateSteps || []).map(function (s) { return s && s.action ? s.action.tool : ''; }).filter(Boolean); } catch (e) { tools = []; }
const time = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm');

const sideNotes = [];
// Nervous patient note on the Patients tab.
if (flags.nervous_patient && /(scared|nervous|afraid|anxious|anxiety|fear|phobia|panic|terrified|خايف|خايفة|بخاف|قلقان|قلقانة|مرعوب|خوف|رعب|متوتر|متوترة)/i.test(text) && !/nervous patient/i.test(String(patient.notes || ''))) {
  sideNotes.push({ kind: 'nervous', phone: phone, notes: patient.notes ? patient.notes + '; nervous patient' : 'nervous patient' });
}
// Every cancel request, in the patient's own words.
if (flags.save_cancellation && /(cancel|cancellation|الغاء|إلغاء|الغي|ألغي|الغى|ألغى|كنسل)/i.test(text)) {
  sideNotes.push({ kind: 'cancel', time: time, phone: phone, service: String(patient.service || ''), reason: 'Request: ' + text.slice(0, 200), saved: 'asked' });
}
// Questions Noor had to hand to the team.
if (flags.unanswered_log && text && /team member will (confirm|reply|get back|check|let you know)|our team will (confirm|check)|هيتواصل|سيتواصل|هيأكد|سيؤكد|هيرد عليك|يتواصل معك/i.test(original)) {
  sideNotes.push({ kind: 'unanswered', time: time, phone: phone, question: text.slice(0, 300), status: 'new' });
}
// A confirmation that was not backed by the calendar.
if (blocked) sideNotes.push({ kind: 'blocked', phone: phone, patient_text: text.slice(0, 300), noor_wanted: original.slice(0, 600) });

return [{ json: { reply: reply, blocked: blocked, tools: tools.join(','), intents: prep.intents, model: prep.model, prompt_chars: prep.prompt_chars, side_notes: sideNotes, test_mode: String(input.test_mode || '') === 'yes' } }];

// One item per side note (skipped in test mode, so tests write nothing to the Sheet).
const f = $('Finalize').first().json;
if (f.test_mode) return [];
return (f.side_notes || []).map(function (n) { return { json: n }; });

