parameters.jsCode:
// Two history rows: the patient's message and the reply actually sent (the corrected one if a reply was blocked).
const input = $('Brain Input').first().json;
const f = $('Finalize').first().json;
return [
  { json: { phone: String(input.phone || ''), role: 'patient', text: String(input.text || '').slice(0, 1500), intents: '' } },
  { json: { phone: String(input.phone || ''), role: 'noor', text: String(f.reply || '').slice(0, 1500), intents: String(f.intents || '') } }
];

// What Noor – Main receives.
const f = $('Finalize').first().json;
return [{ json: { reply: f.reply, blocked: f.blocked, tools: f.tools, intents: f.intents, model: f.model, prompt_chars: f.prompt_chars, side_notes: (f.side_notes || []).map(function (n) { return n.kind; }).join(',') } }];

// Family bookings are saved in the calendar only. If a fresh family event exists for this phone, show the booking guard that a booking was saved.
// Test mode: bookings are dry runs (nothing is written), so pass only when the booking tool itself said Booked or Moved.
const row = $('Re-read Patient').first().json || {};
let tm = false;
try { tm = String($('Brain Input').first().json.test_mode || '') === 'yes'; } catch (e) { tm = false; }
// Website demo chat and Test Suite phones (9715000009...) are dry runs in the Booking Engine too: treat them as test mode.
try { if (/^000000000000/.test(String($('Brain Input').first().json.phone || '').replace(/\D/g, ''))) tm = true; } catch (e) { /* keep */ }
if (tm) {
  let said = false;
  try { said = ($('Noor').first().json.intermediateSteps || []).some(function (st) { return /^(Booked|Moved to)/.test(String((st && st.observation) || '').replace(/^[\s\[\{"']*(response"?\s*:\s*"?)?/i, '')) || /"response"\s*:\s*"(Booked|Moved to)/.test(JSON.stringify(st && st.observation || '')); }); } catch (e) { said = false; }
  if (said) return [{ json: Object.assign({}, row, { calendar_event_id: 'test-dry-run', appointment_start: row.appointment_start || 'test' }) }];
}
let ph = '';
try { ph = String($('Brain Input').first().json.phone || '').replace(/\D/g, ''); } catch (e) { ph = ''; }
const evs = $('Check Family Event').all().map(function (i) { return i.json; });
const fam = evs.find(function (e) {
  const d = String((e && e.description) || '');
  return e && e.id && ph !== '' && /family member/i.test(d) && d.indexOf(ph) >= 0 && (Date.now() - new Date(e.created).getTime()) < 5 * 60 * 1000;
});
if (!fam) return [{ json: row }];
return [{ json: Object.assign({}, row, { calendar_event_id: String(fam.id), appointment_start: row.appointment_start || 'family' }) }];

// Prompt patches, each behind its own switch.
// clinic_setup: clinic details, hours, dentists and prices come from the Clinic Setup / Prices / Dentists tabs.
// family_bookings: books a family member in the calendar instead of logging a request.
// human_style: extra rules so replies sound like a real receptionist texting.
const out = Object.assign({}, $('Prepare').first().json);
const flags = out.flags || {};

function setupRows() { try { return $('Get Setup').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.tab; }); } catch (e) { return []; } }
function money(n) { return Number(n).toLocaleString('en-US'); }

if (typeof out.system === 'string' && flags.clinic_setup) {
  const rows = setupRows().sort(function (a, b) { return Number(a.sort || 0) - Number(b.sort || 0); });
  const c = {};
  rows.filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
  const prices = rows.filter(function (r) { return r.tab === 'price' && r.value !== '' && !isNaN(Number(r.value)); });
  const dentists = rows.filter(function (r) { return r.tab === 'dentist'; });
  if (c.clinic_name) {
    let s = out.system;
    const clinic = c.clinic_name;
    const assistant = c.assistant_name || 'Noor';
    const cur = c.currency || 'AED';
    const slot = Number(c.slot_minutes) || 30;
    const DAYS = ['saturday', 'sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday'];
    const cap = function (d) { return d.charAt(0).toUpperCase() + d.slice(1); };
    const hoursOf = function (d) { const v = String(c['hours_' + d] || '').trim(); return /^\d{1,2}:\d{2}\s*-\s*\d{1,2}:\d{2}$/.test(v) ? v.replace(/\s/g, '') : 'closed'; };
    // Opening hours summary, grouping days with the same hours: "Saturday-Thursday 09:00-21:00, Friday 14:00-21:00"
    const groups = [];
    DAYS.forEach(function (d) { const h = hoursOf(d); const g = groups[groups.length - 1]; if (g && g.h === h) g.to = d; else groups.push({ from: d, to: d, h: h }); });
    const hoursText = groups.map(function (g) { return cap(g.from) + (g.to !== g.from ? '-' + cap(g.to) : '') + ' ' + g.h; }).join(', ');
    const closed = String(c.closed_dates || '').split(/[,;\s]+/).filter(function (x) { return /^\d{4}-\d{2}-\d{2}$/.test(x); });

    s = s.replace(/You are Noor, the WhatsApp assistant for BrightSmile Dental in Dubai \(a fictional demo clinic\)\./, function () { return 'You are ' + assistant + ', the WhatsApp assistant for ' + clinic + ' (' + (c.address || '') + ').'; });
    s = s.split('BrightSmile’s virtual assistant').join(clinic + '’s virtual assistant');

    const dentLine = dentists.length
      ? 'Dentists: ' + dentists.map(function (d) { return d.name + ' (' + [d.value, d.option].filter(Boolean).join('; ') + ')'; }).join(', ') + '.' + (c.languages ? ' ' + c.languages : '')
      : '';
    const basics = [
      clinic + ', ' + (c.address || '') + '.' + (c.parking ? ' ' + c.parking + '.' : '') + ' Open ' + hoursText + '; ' + slot + '-minute slots, last appointment ' + slot + ' minutes before closing.' + (closed.length ? ' Closed on: ' + closed.join(', ') + '.' : ''),
      dentLine,
      [c.payment, c.insurance].filter(Boolean).join(' ')
    ].filter(Boolean).join('\n');
    s = s.replace(/CLINIC BASICS\n[\s\S]*?\n\n/, function () { return 'CLINIC BASICS\n' + basics + '\n\n'; });

    if (prices.length) {
      const list = prices.map(function (p) {
        const from = /^y/i.test(String(p.option || ''));
        return p.name + ' ' + (from ? 'from ' : '') + money(p.value) + (p.notes ? ' (' + p.notes + ')' : '') + (Number(p.minutes) && Number(p.minutes) !== slot ? ' (about ' + p.minutes + ' min)' : '');
      }).join(' | ') + '.';
      s = s.replace(/PRICES \(AED\)\n[^\n]*/, function () { return 'PRICES (' + cur + ')\n' + list; });
    }

    s = s.replace('(Friday opens 14:00, last appointment 20:30)', '(see the opening hours for each day in the calendar below)');
    s = s.replace(/^(- \S+ \d{1,2} \S+ \d{4} = (\d{4}-\d{2}-\d{2}) = [^|\n]*\| )(open [^\n]*|CLOSED)$/gm, function (m, head, ymd) {
      const d = DateTime.fromISO(ymd, { zone: 'Asia/Dubai' });
      const h = hoursOf(DAYS[(d.weekday + 1) % 7]);
      return head + (closed.indexOf(ymd) >= 0 || h === 'closed' ? 'CLOSED' : 'open ' + h);
    });

    const minTotal = Number(c.instalments_min_total) || 2000;
    const months = Number(c.instalments_months) || 6;
    const examples = prices.filter(function (p) { return Number(p.value) > minTotal; }).slice(0, 2)
      .map(function (p) { return p.name.toLowerCase() + ' from ' + cur + ' ' + money(Math.ceil(Number(p.value) / months)) + '/month'; }).join(', ');
    s = s.replace(/MORE than AED 2,000, add one line about 0% instalments over 6 months with the monthly amount \([^)]*\)/, function () {
      return 'MORE than ' + cur + ' ' + money(minTotal) + ', add one line about 0% instalments over ' + months + ' months with the monthly amount' + (examples ? ' (' + examples + ')' : '');
    });
    if (c.emergency_number) s = s.replace('call 998', 'call ' + c.emergency_number);
    s = s.replace('- Location: Jumeirah, Dubai (demo address), free parking.', '- Location: ' + (c.address || '') + (c.parking ? ', ' + c.parking.toLowerCase() : '') + '.');
    out.system = s;
  }
}

if (typeof out.system === 'string' && flags.family_bookings) {
  const OLD = /FAMILY BOOKING: if the patient record shows an upcoming booking[^\n]*/;
  const NEW = 'FAMILY BOOKING: collect the family member’s full name, age (for a child), service and preferred time. For a child use service "children’s check-up" in find_free_slots. Then call book_appointment with the FAMILY MEMBER’s own name, even if this chat already has a booking for someone else (the system keeps it as a separate booking in the calendar). Say it is booked only if the tool says Booked. Never call reschedule_appointment or cancel_appointment for a family member: use log_request with type "family booking" instead. If book_appointment refuses, use log_request and give the request number.';
  out.system = out.system.replace(OLD, function () { return NEW; });
}

if (typeof out.system === 'string' && flags.human_style) {
  const HUMAN = [
    'HUMAN STYLE (most important for how you write)',
    '- Write like a real receptionist texting on WhatsApp: short natural sentences, everyday words, contractions (I’ll, you’re, we’ve). Usually 1 to 3 short sentences, then at most ONE question.',
    '- First react to what they said in a few words (e.g. "Sure!", "Of course", "Oh no, sorry to hear that", "تمام", "أكيد", "ولا يهمك"), then answer. Vary your openers: do not start with "Perfect!" or "Great!", and never reuse the opener of your previous message.',
    '- Do not repeat things they already know (like their existing booking) unless they asked or it matters for this answer.',
    '- Never use the long dash (—) or semicolons. Do not use bullet lists for 3 or fewer items: write them in one sentence, e.g. "I have 10, 11 or 2 on Saturday, which suits you?"',
    '- Avoid robotic phrases: "I have logged", "please be advised", "kindly", "do not hesitate", "feel free", "I understand your concern", "يسعدني إبلاغك", "نود إعلامك". For requests say simply: "I’ve passed this to the team (ref R123), they’ll message you soon."',
    '- Arabic: text the way people do in their dialect, not formal Arabic. Egyptian example: "تمام، عندنا السبت الصبح 10 أو 11، يناسبك أنهي ميعاد؟" Gulf example: "أكيد، عندنا السبت الصبح 10 أو 11، أي وقت يناسبك؟". Follow the speaker’s own gender words (عايز/عايزة, أبي/أبغى); if unclear, use neutral forms.',
    '- Use their first name at most once in a conversation, and only if they told you their name in this chat.',
    '- Times: suggest only times that find_free_slots returned in THIS turn; if you have not called it yet in this turn, call it first. Never describe a booking as existing unless the patient record or my_booking shows it.'
  ].join('\n');
  if (out.system.indexOf('\n\nRULES\n') >= 0) out.system = out.system.replace('\n\nRULES\n', function () { return '\n' + HUMAN + '\n\nRULES\n'; });
  else out.system = out.system + '\n\n' + HUMAN;
}
return [{ json: out }];

// Switch human_style: keep only the last 8 messages of the chat so Noor does not copy old mistakes from long histories.
// Switch satisfaction_check: tells Noor how to answer a 1-5 visit rating (asked by the visit_feedback template).
const out = Object.assign({}, $input.first().json);
const flags = out.flags || {};
if (flags.human_style && typeof out.prompt === 'string') {
  const head = 'RECENT CONVERSATION (oldest first):\n';
  const i = out.prompt.indexOf(head);
  const j = out.prompt.indexOf('\n\nPATIENT’S NEW MESSAGE:');
  if (i === 0 && j > i) {
    const parts = out.prompt.slice(head.length, j).split(/\n(?=(?:Patient|Noor): )/);
    if (parts.length > 8) out.prompt = head + parts.slice(-8).join('\n') + out.prompt.slice(j);
  }
}
if (flags.satisfaction_check && typeof out.system === 'string') {
  let link = '';
  try { const r = $('Get Setup').all().map(function (x) { return x.json || {}; }).find(function (x) { return x.tab === 'clinic' && x.name === 'google_review_link'; }); link = r ? String(r.value || '').trim() : ''; } catch (e) { link = ''; }
  out.system += '\n\nVISIT RATING: after a visit the clinic asks the patient to rate it from 1 to 5. If the patient\'s new message is only a rating (a number from 1 to 5, or words like "5 stars", "excellent", "ممتاز"): for 4 or 5 thank them warmly' + (link ? ' and invite them to leave a short Google review here: ' + link : '') + '. For 1, 2 or 3 apologise sincerely, ask what went wrong, and call alert_staff with the rating and their words. Do not ask for a rating yourself.';
}
// Audit 17 Nov 2026: extra quality rules (language, dialect, greetings, complaints, emergencies, discounts).
if (typeof out.system === 'string') {
  out.system += '\n\nQUALITY RULES (always follow):\n' +
    '1. LANGUAGE: reply in the language of the patient\'s newest message, ignoring any [bracketed note] and older messages. Arabic message = Arabic reply. Arabic written in Latin letters (Arabizi, e.g. "kam se3r") = Arabic reply.\n' +
    '2. DIALECT: mirror the patient\'s dialect. If unclear, use simple Gulf-friendly Arabic. Never mix Egyptian words (بتاع، دلوقتي، عايز، ده) into a Gulf or standard Arabic reply, and never mix Gulf words into an Egyptian reply.\n' +
    '3. GREETINGS: only say good morning / good evening (صباح الخير / مساء الخير) if it matches the Dubai time given above. If unsure, just say hello (أهلاً).\n' +
    '4. COMPLAINTS AND ANGRY PATIENTS: apologise sincerely and specifically for what they described, do not defend the clinic or ask them to repeat themselves. Call alert_staff with a one-line summary, then tell them a team member will contact them today. Never say the team will contact them unless you called alert_staff or log_request in this turn.\n' +
    '5. EMERGENCIES: heavy bleeding that does not stop, facial swelling with fever, trouble breathing or swallowing, or a serious injury: tell them to call 998 (UAE ambulance) or go to the nearest emergency department now, in one or two short lines, then call alert_staff. Do not offer a normal appointment first.\n' +
    '6. DISCOUNTS: never invent a discount or offer. Say the team will check current offers for them and call log_request.\n' +
    '7. Stay inside your role: politely decline unrelated tasks (poems, homework, coding) in one line and offer help with the clinic.';
}
return [{ json: out }];

// Clinic type (Clinic Setup row "clinic_type"): makes Noor fit any clinic, not only dental.
// Values: dental (default, nothing changes), dermatology, aesthetics, cosmetic_surgery, hair, physiotherapy, ivf, general, vet, or any other word.
// Website demo: messages marked [DEMO:glow] answer as the fictional Glow Skin Clinic (information only, no real bookings).
const out = Object.assign({}, $input.first().json);
let type = '';
try { $('Get Setup').all().forEach(function (i) { const r = i.json || {}; if (r.tab === 'clinic' && r.name === 'clinic_type') type = String(r.value || '').trim().toLowerCase(); }); } catch (e) {}
const demo = typeof out.prompt === 'string' && out.prompt.indexOf('[DEMO:glow]') >= 0;
if (demo) { out.prompt = out.prompt.split('[DEMO:glow]').join(''); type = 'aesthetics'; }
if (!type || /^dent/.test(type)) return [{ json: out }];
const T = {
  dermatology: ['dermatology', 'doctor', 'doctors'], aesthetics: ['aesthetics', 'doctor', 'doctors'], cosmetic_surgery: ['cosmetic surgery', 'surgeon', 'surgeons'],
  hair: ['hair restoration', 'doctor', 'doctors'], physiotherapy: ['physiotherapy', 'physiotherapist', 'physiotherapists'], physio: ['physiotherapy', 'physiotherapist', 'physiotherapists'],
  ivf: ['fertility', 'doctor', 'doctors'], fertility: ['fertility', 'doctor', 'doctors'], general: ['medical', 'doctor', 'doctors'], medical: ['medical', 'doctor', 'doctors'],
  vet: ['veterinary', 'vet', 'vets'], veterinary: ['veterinary', 'vet', 'vets']
};
const t = T[type] || [type.replace(/_/g, ' '), 'doctor', 'doctors'];
const cap = function (s) { return s.charAt(0).toUpperCase() + s.slice(1); };
